// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Cloud DB purge: blank old bodies, drop gone rows
// Flo: estimate cloud bytes from the local ledger > under the high mark? stop > blank bodies older than N days (oldest first, in chunks) > still high? delete 404/410 rows older than N days > still high? alert; never more than purg_maxx_pctz of the cap per run
// I/O: Sync (cloud SQL + local Db) + cap bytes + clock (caller) > Dres; the latest record of a live URL is never deleted; dryz only counts
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const hash = @import("ut-hash-dedu.zig");
const CF = .{ .dayz = 86400000, .over = 130, .meta = 400, .chun = 50, .scan = 5000 };
pub const Actd = enum { none, purged, alert, upgr };
pub const Dres = struct { act2: Actd = .none, used: u64 = 0, cap2: u64 = 0, blan: u32 = 0, gone: u32 = 0, free: u64 = 0, limd: bool = false, plan: bool = false };
const Cand = struct { urlh: []const u8, savz: u64 };
pub fn dbzzUsed(dbzz: *@import("st-stor-sqli.zig").Dbzz) !u64 { var stmt = try dbzz.prep("SELECT coalesce(sum(byts),0) FROM dbcl;"); defer stmt.fini(); _ = try stmt.step(); const rawz: u64 = @intCast(@max(stmt.colzIntz(0), 0)); return rawz * CF.over / 100; }
fn ledgByts(self: *sync.Sync, urlk: []const u8) !i64 { var stmt = try self.dbzz.prep("SELECT byts FROM dbcl WHERE urlh=?1;"); defer stmt.fini(); try stmt.bindText(1, urlk); if (!try stmt.step()) return -1; return stmt.colzIntz(0); }
fn inzzList(aren: std.mem.Allocator, self: *sync.Sync, cand: []const Cand) ![]u8 { var outp: std.ArrayList(u8) = .empty; for (cand, 0..) |item, indx| { if (indx > 0) try outp.append(aren, ','); try outp.appendSlice(aren, try sqlz.litz(aren, self.sql2.dial, item.urlh)); } return outp.toOwnedSlice(aren); }
fn blanChun(self: *sync.Sync, aren: std.mem.Allocator, cand: []const Cand) !void { const stmz = [_][]const u8{try std.fmt.allocPrint(aren, "UPDATE cl_reco SET body='' WHERE urlh IN ({s})", .{try inzzList(aren, self, cand)})}; try self.sql2.exec(self.sql2.ctx2, aren, self.iozz, &stmz); for (cand) |item| try sync.ledgSetz(self.dbzz, item.urlh, CF.meta); }
fn goneChun(self: *sync.Sync, aren: std.mem.Allocator, cand: []const Cand) !void { const inzz = try inzzList(aren, self, cand); const stmz = [_][]const u8{ try std.fmt.allocPrint(aren, "DELETE FROM cl_page WHERE urlh IN ({s})", .{inzz}), try std.fmt.allocPrint(aren, "DELETE FROM cl_reco WHERE urlh IN ({s})", .{inzz}) }; try self.sql2.exec(self.sql2.ctx2, aren, self.iozz, &stmz); for (cand) |item| { var stmt = try self.dbzz.prep("DELETE FROM dbcl WHERE urlh=?1;"); defer stmt.fini(); try stmt.bindText(1, item.urlh); _ = try stmt.step(); } }
fn runzChun(self: *sync.Sync, aren: std.mem.Allocator, list: []const Cand, gone: bool, rslt: *Dres, lowz: u64, maxb: u64) !void { var posi: usize = 0; while (posi < list.len) { if (rslt.used - rslt.free <= lowz) return; if (rslt.free >= maxb) { rslt.limd = true; return; } const endz = @min(posi + CF.chun, list.len); const part = list[posi..endz]; var savz: u64 = 0; for (part) |item| savz += item.savz; if (!self.dryz) { if (gone) try goneChun(self, aren, part) else try blanChun(self, aren, part); } rslt.free += savz; if (gone) rslt.gone += @intCast(part.len) else rslt.blan += @intCast(part.len); posi = endz; } }
fn candBlan(self: *sync.Sync, aren: std.mem.Allocator, cutz: i64) ![]Cand { var stmt = try self.dbzz.prep("SELECT urlz FROM reco WHERE timz<?1 ORDER BY timz LIMIT ?2;"); defer stmt.fini(); try stmt.bindIntz(1, cutz); try stmt.bindIntz(2, CF.scan); var list: std.ArrayList(Cand) = .empty; while (try stmt.step()) { const urlk = try aren.dupe(u8, &hash.hashHexz(stmt.colzText(0))); const byts = try ledgByts(self, urlk); if (byts <= CF.meta) continue; try list.append(aren, .{ .urlh = urlk, .savz = @as(u64, @intCast(byts - CF.meta)) * CF.over / 100 }); } return list.toOwnedSlice(aren); }
fn candGone(self: *sync.Sync, aren: std.mem.Allocator, cutz: i64) ![]Cand { var stmt = try self.dbzz.prep("SELECT urlz FROM page WHERE code IN (404,410) AND fetc<?1 ORDER BY fetc LIMIT ?2;"); defer stmt.fini(); try stmt.bindIntz(1, cutz); try stmt.bindIntz(2, CF.scan); var list: std.ArrayList(Cand) = .empty; while (try stmt.step()) { const urlk = try aren.dupe(u8, &hash.hashHexz(stmt.colzText(0))); const byts = try ledgByts(self, urlk); if (byts < 0) continue; try list.append(aren, .{ .urlh = urlk, .savz = @as(u64, @intCast(byts)) * CF.over / 100 }); } return list.toOwnedSlice(aren); }
pub fn dbzzRunz(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64, capb: u64) !Dres { var rslt: Dres = .{ .cap2 = capb, .plan = self.dryz }; rslt.used = try dbzzUsed(self.dbzz); const conf = self.conf; const high = capb * conf.purg_high_pctz / 100; const lowz = capb * conf.purg_lowz_pctz / 100; const maxb = capb * conf.purg_maxx_pctz / 100; if (capb == 0 or rslt.used < high) return rslt; if (std.mem.eql(u8, conf.clou_poli_mode, "upgr")) { rslt.act2 = .upgr; return rslt; } try runzChun(self, aren, try candBlan(self, aren, nowz - @as(i64, conf.purg_dbzz_body_days) * CF.dayz), false, &rslt, lowz, maxb); try runzChun(self, aren, try candGone(self, aren, nowz - @as(i64, conf.purg_dbzz_gone_days) * CF.dayz), true, &rslt, lowz, maxb); if (rslt.free > 0) rslt.act2 = .purged; if (rslt.used - rslt.free >= high) rslt.act2 = .alert; return rslt; }
